mapper.select:
SELECT m.* FROM mail_message m JOIN customer c ON c.organization_id = m.organization_id AND c.id = m.customer_id AND c.deleted_at IS NULL
WHERE m.organization_id = #{org} AND m.direction = 'OUTBOUND' AND m.status IN ('SENT', 'UNKNOWN')
  AND m.message_id IN #{ref}
  AND m.recipients @> jsonb_build_array(CAST(#{sender} AS text))
  AND m.from_address IN #{recipient}
ORDER BY m.occurred_at DESC, m.id LIMIT 1
